Function r <- Cuadrado(n As Integer)
  Define r As Integer;
  Write "calculando";
  r <- n * n;
End Function

Algorithm Principal
  Write Cuadrado(3);
EndAlgorithm

Subroutine Avisar()
  Write "aviso";
EndSubroutine

Function r <- Triple(n As Integer)
  Define r As Integer;
  Avisar();
  r <- n * 3;
End Function

Algorithm Principal
  Write Triple(3);
EndAlgorithm
